using System;
using System.Linq;
using EmberBastion;
class ReinforcementPlaythroughChecks {
 static int Main(){try{int won=0,lost=0;foreach(uint seed in new uint[]{29,41,57,73})for(int field=0;field<3;field++){var b=new Battle(seed,field);if(!b.EnableReinforcements())throw new Exception("mode");int ticks=0,picks=0;while(b.Phase!=Phase.Won&&b.Phase!=Phase.Lost&&ticks<120000){if(b.ReinforcementPending){var options=b.Reinforcements.Choices();var restored=Battle.ImportCombat(b.ExportCombat());if(!options.SequenceEqual(restored.Reinforcements.Choices()))throw new Exception("pending offer changed after save");b=restored;if(!b.ChooseReinforcement(options[0]))throw new Exception("choice failed");picks++;}if(ticks%60==0){for(int slot=0;slot<b.Field.Slots.Length;slot++)if(b.At(slot)==null){int kind=Smart.Kind(field,slot);if(b.Gold>=Balance.Troops[kind].Cost)b.Place(kind,slot);}foreach(var u in b.Units){if(u.Level==1&&b.Gold>=50)b.Upgrade(u.Slot);else if(u.Kind==0&&u.Level==2&&b.Gold>=90)b.UpgradeBranch(u.Slot,2);}}if(b.Phase==Phase.Preparation&&!b.Start())throw new Exception("start failed");if(b.EmberCD<=0&&b.Enemies.Count>=3)b.Ember(b.Enemies[b.Enemies.Count/2].Position);b.Step(1.0/60);ticks++;}if(b.Phase==Phase.Fighting)throw new Exception("stalled");if(b.Phase==Phase.Won){won++;if(picks!=2)throw new Exception("winner missed a selection");}else lost++;}Console.WriteLine("PASS 12 reinforcement playthroughs with pending restore; wins "+won+", losses "+lost);return 0;}catch(Exception e){Console.Error.WriteLine(e.Message);return 1;}}
}
static class Smart {
 static readonly System.Collections.Generic.Dictionary<int,int[]> cache=new System.Collections.Generic.Dictionary<int,int[]>();
 static Point P(int f,double d){return f==0?Balance.Path(d):Balance.Fields[f].Path(d);}
 static double Cover(int f,Point s,double range,double min){double per=f==0?Balance.Perimeter:Balance.Fields[f].Perimeter;int n=0,inside=0;for(double d=0;d<per;d+=16){n++;double dist=Point.Distance(P(f,d),s);if(dist<=range&&dist>=min)inside++;}return (double)inside/n;}
 // Swords on the half of slots that touch the most road within melee range; the rest alternate archer/bomb by long-range coverage.
 public static int Kind(int f,int slot){int[] a;if(!cache.TryGetValue(f,out a)){var S=Balance.Fields[f].Slots;int m=S.Length;var idx=new System.Collections.Generic.List<int>();for(int i=0;i<m;i++)idx.Add(i);idx.Sort((x,y)=>{int comparison=Cover(f,S[y],120,0).CompareTo(Cover(f,S[x],120,0));return comparison!=0?comparison:x.CompareTo(y);});a=new int[m];var rest=new System.Collections.Generic.List<int>();for(int i=0;i<m;i++){if(i<m/2)a[idx[i]]=0;else rest.Add(idx[i]);}rest.Sort((x,y)=>{int comparison=Cover(f,S[y],210,60).CompareTo(Cover(f,S[x],210,60));return comparison!=0?comparison:x.CompareTo(y);});for(int i=0;i<rest.Count;i++)a[rest[i]]=i%2==0?1:2;cache[f]=a;}return a[slot];}
}
